import{_ as t,o as n,c as a,a0 as s}from"./chunks/framework.CWg_RwV0.js";const u=JSON.parse('{"title":"Agentic nPort","description":"","frontmatter":{},"headers":[],"relativePath":"agentic-nport.md","filePath":"agentic-nport.md"}'),r={name:"agentic-nport.md"};function i(o,e,d,l,c,h){return n(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="agentic-nport" tabindex="-1">Agentic nPort <a class="header-anchor" href="#agentic-nport" aria-label="Permalink to &quot;Agentic nPort&quot;">​</a></h1><p><strong>Describe your circuit. Let your agent write the nP code.</strong> Give Codex, Claude or another coding assistant your requirements, existing code, or a scanned or hand-drawn schematic. The nP agent supplies the library knowledge and writes explicit code with named components, connections and results.</p><p>You can work in an ordinary folder outside this repository. Download the instructions for your environment and supply its nP library; no repository checkout is needed.</p><h2 id="choose-your-environment" tabindex="-1">Choose your environment <a class="header-anchor" href="#choose-your-environment" aria-label="Permalink to &quot;Choose your environment&quot;">​</a></h2><p>Save the chosen instruction file as <code>AGENTS.md</code> in your working folder. If that folder already has agent instructions, preserve them and ask your coding assistant to read the nP instructions from a separate location.</p><table tabindex="0"><thead><tr><th>Environment</th><th>Agent instructions</th><th>What it uses</th></tr></thead><tbody><tr><td>Standalone HTML</td><td><a href="https://raw.githubusercontent.com/JerryWiltz/nP/master/nP-agents/html/AGENTS.md" target="_blank" rel="noreferrer">HTML agent</a></td><td>A local <a href="./nP.js">nP.js browser bundle</a>.</td></tr><tr><td>Node.js</td><td><a href="https://raw.githubusercontent.com/JerryWiltz/nP/master/nP-agents/nodejs/AGENTS.md" target="_blank" rel="noreferrer">Node.js agent</a></td><td>A local <a href="https://raw.githubusercontent.com/JerryWiltz/nP/master/dist/nP.cjs" target="_blank" rel="noreferrer">nP.cjs bundle</a> or an installed <code>@jerrywiltz/np</code> package.</td></tr><tr><td>Existing website</td><td><a href="https://raw.githubusercontent.com/JerryWiltz/nP/master/nP-agents/websites/AGENTS.md" target="_blank" rel="noreferrer">Website agent</a></td><td>The site&#39;s nP bundle or installed package and existing page structure.</td></tr><tr><td>Obsidian</td><td><a href="https://raw.githubusercontent.com/JerryWiltz/nP/master/nP-agents/obsidian/AGENTS.md" target="_blank" rel="noreferrer">Obsidian agent</a></td><td>The nP library supplied by the nPort RF Analysis plugin.</td></tr></tbody></table><p>Each instruction file stands alone. Locally supplied nP bundles support offline analysis; your coding assistant has its own connection requirements. The instructions describe the intended APIs and check the capabilities of the supplied library when needed. A matching version number alone does not establish that every build has the same features.</p><h2 id="create-a-standalone-html" tabindex="-1">Create a standalone HTML <a class="header-anchor" href="#create-a-standalone-html" aria-label="Permalink to &quot;Create a standalone HTML&quot;">​</a></h2><p>Put the HTML agent and browser bundle in a fresh folder:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-circuit/</span></span>
<span class="line"><span>├── AGENTS.md</span></span>
<span class="line"><span>└── nP.js</span></span></code></pre></div><p>Start a coding-assistant session in that folder and ask it to read <code>AGENTS.md</code>. Then describe the circuit and result you want. For example:</p><blockquote><p>Create an HTML file for a matched 50-ohm transmission line 25 mm long. Show its schematic and plot S21 phase from 1 to 3 GHz with 51 points.</p></blockquote><p>The agent writes the HTML. Open the resulting file in a browser. For a drawing input, include readable component values and indicate which wire crossings connect. The agent can ask about ambiguous values or connections.</p><h2 id="work-in-node-js" tabindex="-1">Work in Node.js <a class="header-anchor" href="#work-in-node-js" aria-label="Permalink to &quot;Work in Node.js&quot;">​</a></h2><p>For the standalone CommonJS setup, use:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-calculation/</span></span>
<span class="line"><span>├── AGENTS.md</span></span>
<span class="line"><span>└── nP.cjs</span></span></code></pre></div><p>Use the Node.js agent in this folder. For example:</p><blockquote><p>Write and run a Node.js script that reports S11 and S21 for a 5 nH series inductor at 2 GHz, with 50-ohm reference impedances.</p></blockquote><p>The agent writes a <code>.cjs</code> script using the adjacent bundle. A project with the npm package can instead use an ES-module script. Node calculations use terminal tables or requested data files; browser chart helpers need a browser environment.</p><h2 id="use-an-existing-website-or-obsidian-vault" tabindex="-1">Use an existing website or Obsidian vault <a class="header-anchor" href="#use-an-existing-website-or-obsidian-vault" aria-label="Permalink to &quot;Use an existing website or Obsidian vault&quot;">​</a></h2><p>For a website, provide its existing project and the website agent. Describe where the result belongs. It uses the site&#39;s loading and lifecycle conventions and mounts nP output in the intended page section.</p><p>For Obsidian, start your coding-assistant session at the vault root and explicitly ask it to read the Obsidian agent file. Development builds of nPort RF Analysis include that file in the plugin folder; published plugin releases may not yet include it. If absent, use the downloaded instructions. The plugin supplies its own pinned nP library, so do not copy a browser bundle into the vault.</p><p>Ask for a note containing the requested circuit and results. The agent writes an <code>npjs</code> block. Open the note in Reading view and select <strong>Run</strong>. See <a href="./using-the-repl.html">Using the REPL</a> for the separate browser playground.</p><h2 id="keep-the-request-simple" tabindex="-1">Keep the request simple <a class="header-anchor" href="#keep-the-request-simple" aria-label="Permalink to &quot;Keep the request simple&quot;">​</a></h2><p>State the circuit or desired behavior, known values, frequency or time range, and requested outputs. You do not need to choose nP constructors or type the JavaScript. Existing code and viewable sketches are valid starting points.</p><p>By default the agent writes code. Ask it to run or verify the result when you want that work too. It keeps the circuit steps visible and uses nP&#39;s built-in displays. Further explanation is available when you ask for it.</p><p>For the manual first example, continue to <a href="./hello-nport.html">Hello nPort</a>. The <a href="./introduction.html">Introduction</a> explains the main nP workflows.</p>`,27)])])}const b=t(r,[["render",i]]);export{u as __pageData,b as default};
